import 'package:flutter/widgets.dart';

import '../../../../../core/theme/app_colors.dart';

/// The app logo tile: gradient rounded square with the white folded-map glyph.
///
/// This is the same artwork as the launcher icon, favicon and web splash
/// (generated by `tool/branding/generate_icons.ps1` from the same polygons), so
/// the icon looks identical everywhere. It is drawn as vectors, so it is exactly
/// centred and independent of font metrics on every platform.
class LogoMark extends StatelessWidget {
  const LogoMark({super.key});

  static const double size = 32;

  @override
  Widget build(BuildContext context) {
    return DecoratedBox(
      decoration: BoxDecoration(
        gradient: AppColors.brandGradient,
        // Same 20% corner radius as the generated launcher/favicon PNGs.
        borderRadius: BorderRadius.circular(size * 0.2),
      ),
      child: const SizedBox(
        width: size,
        height: size,
        child: CustomPaint(painter: _MapGlyphPainter()),
      ),
    );
  }
}

class _MapGlyphPainter extends CustomPainter {
  const _MapGlyphPainter();

  /// Three folded-map panels in a 100x100 design space, centred on (50, 51):
  /// the same polygons as the icon generator.
  static const List<List<Offset>> _panels = [
    [Offset(21, 31), Offset(40, 24), Offset(40, 71), Offset(21, 78)],
    [Offset(42, 24), Offset(58, 31), Offset(58, 78), Offset(42, 71)],
    [Offset(60, 31), Offset(79, 24), Offset(79, 71), Offset(60, 78)],
  ];

  /// Outer panels are slightly translucent (215/255), the middle is solid.
  static const List<double> _opacity = [215 / 255, 1, 215 / 255];

  @override
  void paint(Canvas canvas, Size size) {
    final k = size.width / 100;
    // Map the glyph's visual centre (50, 51) to the tile centre.
    final shift = Offset(size.width / 2 - 50 * k, size.height / 2 - 51 * k);
    for (var i = 0; i < _panels.length; i++) {
      final path = Path();
      for (var j = 0; j < _panels[i].length; j++) {
        final p = _panels[i][j] * k + shift;
        if (j == 0) {
          path.moveTo(p.dx, p.dy);
        } else {
          path.lineTo(p.dx, p.dy);
        }
      }
      path.close();
      canvas.drawPath(
        path,
        Paint()
          ..isAntiAlias = true
          ..color = const Color(0xFFFFFFFF).withValues(alpha: _opacity[i]),
      );
    }
  }

  @override
  bool shouldRepaint(_MapGlyphPainter oldDelegate) => false;
}
